{{ assert_case_vars() }}
with business as (select
    CAST(f.tenant_id AS String) AS `tenant_id`,
    CAST(f.opportunity_key AS String) AS `opportunity_key`,
    CAST(f.opportunity_id AS Int64) AS `opportunity_id`,
    CAST(f.company_key AS Nullable(String)) AS `company_key`,
    CAST(f.company_version_key AS Nullable(String)) AS `company_version_key`,
    CAST(f.company_id AS Nullable(Int64)) AS `company_id`,
    CAST(co.company_name AS Nullable(String)) AS `company_name`,
    CAST(f.followup_key AS String) AS `followup_key`,
    CAST(f.followup_definition_key AS String) AS `followup_definition_key`,
    CAST(f.followup_definition_version_key AS Nullable(String)) AS `followup_definition_version_key`,
    CAST(f.created_at AS Nullable(DateTime64(3, 'UTC'))) AS `created_at`,
    CAST(f.anchor_key AS String) AS `anchor_key`,
    CAST(f.anchor_at AS Nullable(DateTime64(3, 'UTC'))) AS `anchor_at`,
    CAST(f.cohort_month AS Nullable(Date)) AS `cohort_month`,
    CAST(f.horizon_days AS Nullable(UInt16)) AS `horizon_days`,
    CAST(f.horizon_at AS Nullable(DateTime64(3, 'UTC'))) AS `horizon_at`,
    CAST(f.cohort_mature_at AS Nullable(DateTime64(3, 'UTC'))) AS `cohort_mature_at`,
    CAST(f.issue_at_horizon AS Nullable(String)) AS `issue_at_horizon`,
    CAST(f.is_eligible AS Nullable(Bool)) AS `is_eligible`,
    CAST(f.is_mature AS Nullable(Bool)) AS `is_mature`,
    CAST(f.is_cohort_mature AS Nullable(Bool)) AS `is_cohort_mature`,
    CAST(f.is_observable AS Nullable(Bool)) AS `is_observable`,
    CAST(f.coverage_start_at AS Nullable(DateTime64(3, 'UTC'))) AS `coverage_start_at`,
    CAST(f.coverage_end_at AS Nullable(DateTime64(3, 'UTC'))) AS `coverage_end_at`,
    CAST(f.is_history_complete AS Nullable(Bool)) AS `is_history_complete`,
    CAST(1 AS UInt8) AS `nb_cohort_membership`,
    CAST(f.denominator_contribution AS Nullable(UInt8)) AS `denominator_contribution`,
    CAST(f.open_contribution AS Nullable(UInt8)) AS `open_contribution`,
    CAST(f.won_contribution AS Nullable(UInt8)) AS `won_contribution`,
    CAST(f.lost_contribution AS Nullable(UInt8)) AS `lost_contribution`,
    CAST(f.abandoned_contribution AS Nullable(UInt8)) AS `abandoned_contribution`,
    CAST(f.unqualified_contribution AS Nullable(UInt8)) AS `unqualified_contribution`,
    CAST(f.unknown_contribution AS Nullable(UInt8)) AS `unknown_contribution`,
    CAST(f.sale_type_id AS Nullable(Int64)) AS `sale_type_id`,
    CAST(f.sale_type_key AS Nullable(String)) AS `sale_type_key`,
    CAST(f.sale_type_version_key AS Nullable(String)) AS `sale_type_version_key`,
    CAST(ty.sale_type_label AS Nullable(String)) AS `sale_type_label`,
    CAST(f.acquisition_channel_key AS Nullable(String)) AS `channel_key`,
    CAST(f.channel_version_key AS Nullable(String)) AS `channel_version_key`,
    CAST(ch.channel_label AS Nullable(String)) AS `channel_label`,
    CAST(f.channel_candidate_code AS Nullable(String)) AS `channel_candidate_code`,
    CAST(f.is_channel_calculable AS Bool) AS `is_channel_calculable`,
    CAST(f.employee_key AS Nullable(String)) AS `employee_key`,
    CAST(f.employee_version_key AS Nullable(String)) AS `employee_version_key`,
    CAST(em.employee_display_name AS Nullable(String)) AS `employee_display_name`,
    CAST(f.team_key AS Nullable(String)) AS `team_key`,
    CAST(f.team_version_key AS Nullable(String)) AS `team_version_key`,
    CAST(tm.team_name AS Nullable(String)) AS `team_name`,
    CAST(f.is_team_calculable AS Bool) AS `is_team_calculable`,
    CAST(f.calculation_status AS String) AS `calculation_status`,
    CAST(f.status_reason AS Nullable(String)) AS `status_reason`
from {{ ref('fct_opportunity_followup') }} f left join {{ ref('dim_company') }} co on f.model_run_id=co.model_run_id and f.company_version_key=co.company_version_key left join {{ ref('dim_sale_type') }} ty on f.model_run_id=ty.model_run_id and f.sale_type_version_key=ty.sale_type_version_key left join {{ ref('dim_channel') }} ch on f.model_run_id=ch.model_run_id and f.channel_version_key=ch.channel_version_key left join {{ ref('dim_employee') }} em on f.model_run_id=em.model_run_id and f.employee_version_key=em.employee_version_key left join {{ ref('dim_team') }} tm on f.model_run_id=tm.model_run_id and f.team_version_key=tm.team_version_key where f.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} and f.followup_kind='cohort_outcome'),
